(function(){
  // Loader: prefer embedded official axe-core if present at `src/content/axe-core.min.js`.
  // Fallback: small compatible shim retained for offline/dev convenience.
  if (window.__UI_AGENT_AXE_INSTALLED__) return;
  window.__UI_AGENT_AXE_INSTALLED__ = true;

  function loadVendorAxe(srcUrl) {
    return new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = srcUrl;
      s.onload = () => resolve(true);
      s.onerror = () => reject(new Error('vendor axe load failed'));
      (document.head || document.documentElement).appendChild(s);
    });
  }

  async function ensureAxe() {
    // try to load vendor axe if it exists in the extension package
    try {
      const vendor = chrome.runtime.getURL('src/content/axe-core.min.js');
      await loadVendorAxe(vendor);
      if (window.axe) return;
    } catch (e) {
      // vendor not available — fall back to shim below
    }

    // Minimal shim (kept for development only) — ensures `axe.run` exists with compatible shape.
    window.axe = window.axe || {
      run: async function(context, options){
        const violations = [];
        try {
          const imgs = Array.from(document.querySelectorAll('img'));
          const imgNodes = imgs.filter(img => !img.alt || img.alt.trim() === '').map(img => ({ target: [simpleSelector(img)], html: img.outerHTML, failureSummary: 'Image missing alt attribute' }));
          if (imgNodes.length) violations.push({ id: 'image-alt', impact: 'serious', description: 'Images should have alt text', nodes: imgNodes });

          const inputs = Array.from(document.querySelectorAll('input:not([type=hidden])'));
          const unlabeled = inputs.filter(i => {
            if (i.getAttribute('aria-label')) return false;
            if (i.getAttribute('aria-labelledby')) return false;
            if (i.id && document.querySelector(`label[for="${i.id}"]`)) return false;
            return true;
          }).map(i => ({ target: [simpleSelector(i)], html: i.outerHTML, failureSummary: 'Form control missing visible label' }));
          if (unlabeled.length) violations.push({ id: 'label', impact: 'moderate', description: 'Form controls require labels', nodes: unlabeled });

          const controls = Array.from(document.querySelectorAll('a,button,input[type=submit],input[type=button]'));
          const nameless = controls.filter(el => { const text = (el.innerText || el.value || '').trim(); const aria = el.getAttribute && el.getAttribute('aria-label'); return !text && !aria; }).map(el => ({ target: [simpleSelector(el)], html: el.outerHTML, failureSummary: 'Control has no accessible name' }));
          if (nameless.length) violations.push({ id: 'link-name', impact: 'moderate', description: 'Interactive controls must have accessible names', nodes: nameless });

          const headings = Array.from(document.querySelectorAll('h1,h2,h3,h4,h5,h6'));
          let lastLevel = 0; const headingNodes = [];
          headings.forEach(h => { const level = parseInt(h.tagName[1], 10); if (lastLevel && level > lastLevel + 1) headingNodes.push({ target: [simpleSelector(h)], html: h.outerHTML, failureSummary: `Heading jumps from ${lastLevel} to ${level}` }); lastLevel = level; });
          if (headingNodes.length) violations.push({ id: 'heading-order', impact: 'minor', description: 'Headings should not skip levels', nodes: headingNodes });
        } catch (e) { /* graceful fallback */ }
        return { violations, timestamp: Date.now() };
      }
    };

    function simpleSelector(el){ if (!el) return ''; if (el.id) return `#${el.id}`; if (el.className && typeof el.className === 'string') return `${el.tagName.toLowerCase()}.${el.className.split(/\s+/).join('.')}`; return el.tagName.toLowerCase(); }
  }

  ensureAxe().catch(()=>{});

  // respond to postMessage runner requests from content script
  window.addEventListener('message', async function(ev){
    if (!ev.data || ev.data.direction !== 'ui-agent') return;
    if (ev.data.type === 'RUN_AXE') {
      try {
        const res = await window.axe.run(document, ev.data.options || {});
        window.postMessage({ direction: 'ui-agent', type: 'AXE_RESULT', payload: res }, '*');
      } catch (err) {
        window.postMessage({ direction: 'ui-agent', type: 'AXE_RESULT', payload: { violations: [], error: String(err) } }, '*');
      }
    }
  });
})();